BEGIN;
CREATE TEMP TABLE b6w(site TEXT,stream TEXT,stage TEXT,flow REAL,unit TEXT,basis TEXT,poll TEXT,proc TEXT,dest TEXT,res TEXT,src TEXT,conf TEXT,note TEXT);
CREATE TEMP TABLE b6c(site TEXT,product TEXT,value REAL,unit TEXT,basis TEXT,period TEXT,scope TEXT,src TEXT,note TEXT);
CREATE TEMP TABLE b6m(site TEXT,wrow INTEGER,point TEXT,metric TEXT,num REAL,txt TEXT,unit TEXT,kind TEXT,period TEXT,src TEXT,note TEXT);
CREATE TABLE water_economics(cost_id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites,water_id TEXT REFERENCES wastewater,item TEXT NOT NULL,value REAL NOT NULL,unit TEXT NOT NULL,basis TEXT NOT NULL,period TEXT,source_id TEXT NOT NULL REFERENCES sources,notes TEXT);
CREATE TEMP TABLE b6u(site TEXT,src TEXT,level TEXT,summary TEXT,next TEXT);
UPDATE sites SET water_level=coalesce((SELECT level FROM b6u WHERE site=site_id),water_level),water_summary=coalesce(water_summary||'；','')||(SELECT summary FROM b6u WHERE site=site_id),source_status='部分本轮复核',as_of='2026-11-27' WHERE site_id IN (SELECT site FROM b6u);
UPDATE sites SET address='新密市产业集聚区风尚街北侧',capacity_summary='企业披露新剂3万m³/年、再生及处置1万m³/年；历史6000m³项目另列' WHERE site_id='CN0174';
UPDATE sites SET capacity_summary=coalesce(capacity_summary||'；','')||'2026招标披露废SCR利用2万吨/年（非新剂）' WHERE site_id='CN0060';
UPDATE tasks SET next_query=(SELECT next FROM b6u WHERE site=site_id),state='部分完成' WHERE site_id IN (SELECT site FROM b6u);
INSERT OR IGNORE INTO site_sources SELECT site,src FROM b6w UNION SELECT site,src FROM b6c UNION SELECT site,src FROM b6u UNION SELECT 'CN0225','W06S08' UNION SELECT 'CN0227','W06S11' UNION SELECT 'CN0228','W06S12' UNION SELECT 'CN0226','W06S28' UNION SELECT 'CN0174','W06S03' UNION SELECT 'CN0060','W06S15';
DROP TABLE b6w; DROP TABLE b6c; DROP TABLE b6m; DROP TABLE b6u;

COMMIT;
